begin;
create table if not exists public.team_calendar_events(id uuid primary key default gen_random_uuid(),title text not null,description text,event_type text not null default 'team_event' check(event_type in ('team_event','fundraising','competition','training','deadline','meeting','other')),starts_at timestamptz not null,ends_at timestamptz not null,all_day boolean not null default false,location text,target_type text not null default 'all' check(target_type in ('all','subteam','member')),target_value text,mandatory boolean not null default false,created_by uuid references public.team_members(id) on delete set null default auth.uid(),cancelled boolean not null default false,created_at timestamptz not null default now(),check(ends_at>=starts_at));
create table if not exists public.training_courses(id uuid primary key default gen_random_uuid(),title text not null,description text not null,domain text not null,target_subteam text,required boolean not null default false,active boolean not null default true,created_by uuid references public.team_members(id) on delete set null default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.training_modules(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.training_courses(id) on delete cascade,title text not null,instructions text not null,sort_order integer not null default 100,evidence_required boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.training_enrollments(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.training_courses(id) on delete cascade,member_id uuid not null references public.team_members(id) on delete cascade,status text not null default 'assigned' check(status in ('assigned','in_progress','submitted','qualified')),assigned_by uuid references public.team_members(id) on delete set null default auth.uid(),due_at date,created_at timestamptz not null default now(),unique(course_id,member_id));
create table if not exists public.training_evidence(id uuid primary key default gen_random_uuid(),enrollment_id uuid not null references public.training_enrollments(id) on delete cascade,module_id uuid not null references public.training_modules(id) on delete cascade,member_id uuid not null references public.team_members(id) on delete cascade,note text not null,status text not null default 'submitted' check(status in ('submitted','approved','changes_requested')),review_note text,reviewed_by uuid references public.team_members(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['team_calendar_events','training_courses','training_modules','training_enrollments','training_evidence'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "members view %1$s" on public.%1$I',t);execute format('create policy "members view %1$s" on public.%1$I for select to authenticated using(public.current_team_role() is not null)',t);execute format('drop policy if exists "members create %1$s" on public.%1$I',t);execute format('create policy "members create %1$s" on public.%1$I for insert to authenticated with check(public.current_team_role() is not null)',t);execute format('drop policy if exists "members update %1$s" on public.%1$I',t);execute format('create policy "members update %1$s" on public.%1$I for update to authenticated using(public.current_team_role() is not null) with check(public.current_team_role() is not null)',t);end loop;end$$;
drop policy if exists "members create team_calendar_events" on public.team_calendar_events;drop policy if exists "members update team_calendar_events" on public.team_calendar_events;create policy "admins create calendar events" on public.team_calendar_events for insert to authenticated with check(public.is_admin());create policy "admins update calendar events" on public.team_calendar_events for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members create training_courses" on public.training_courses;drop policy if exists "members update training_courses" on public.training_courses;create policy "admins create courses" on public.training_courses for insert to authenticated with check(public.is_admin());create policy "admins update courses" on public.training_courses for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members create training_modules" on public.training_modules;drop policy if exists "members update training_modules" on public.training_modules;create policy "admins create modules" on public.training_modules for insert to authenticated with check(public.is_admin());create policy "admins update modules" on public.training_modules for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members create training_enrollments" on public.training_enrollments;drop policy if exists "members update training_enrollments" on public.training_enrollments;create policy "admins create enrollments" on public.training_enrollments for insert to authenticated with check(public.is_admin());create policy "admins update enrollments" on public.training_enrollments for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members create training_evidence" on public.training_evidence;drop policy if exists "members update training_evidence" on public.training_evidence;create policy "members submit own evidence" on public.training_evidence for insert to authenticated with check(member_id=auth.uid());create policy "admins review evidence" on public.training_evidence for update to authenticated using(public.is_admin()) with check(public.is_admin());
create unique index if not exists training_evidence_one_per_module on public.training_evidence(enrollment_id,module_id);
insert into public.team_calendar_events(title,description,event_type,starts_at,ends_at,all_day,location,target_type,mandatory,created_by) select title,null,'meeting',starts_at,ends_at,false,null,'all',false,created_by from public.team_meetings m where not exists(select 1 from public.team_calendar_events c where c.title=m.title and c.starts_at=m.starts_at);
create or replace function public.publish_milestone_calendar_event() returns trigger language plpgsql security definer set search_path=public as $$begin if new.due_at is not null then insert into public.team_calendar_events(title,description,event_type,starts_at,ends_at,all_day,target_type,target_value,mandatory,created_by) values(new.title,new.details,'deadline',new.due_at::timestamptz,new.due_at::timestamptz+interval '23 hours 59 minutes',true,case when new.owner_id is not null then 'member' when new.workstream='team' then 'all' else 'subteam' end,case when new.owner_id is not null then new.owner_id::text when new.workstream='team' then null else new.workstream end,true,new.created_by);end if;return new;end$$;
drop trigger if exists milestone_to_calendar on public.season_milestones;create trigger milestone_to_calendar after insert on public.season_milestones for each row execute function public.publish_milestone_calendar_event();
insert into public.team_calendar_events(title,description,event_type,starts_at,ends_at,all_day,target_type,target_value,mandatory,created_by) select m.title,m.details,'deadline',m.due_at::timestamptz,m.due_at::timestamptz+interval '23 hours 59 minutes',true,case when m.owner_id is not null then 'member' when m.workstream='team' then 'all' else 'subteam' end,case when m.owner_id is not null then m.owner_id::text when m.workstream='team' then null else m.workstream end,true,m.created_by from public.season_milestones m where m.due_at is not null and not exists(select 1 from public.team_calendar_events c where c.title=m.title and c.starts_at::date=m.due_at);
commit;
